import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            Assert.fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        Complex c = new Complex(Double.NaN, 1.0);
        Complex divisor = new Complex(1.0, 1.0);
        Complex result = c.divide(divisor);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_DivisorNaN_Result() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(Double.NaN, 1.0);
        Complex result = c.divide(divisor);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_DivideByZero_Result() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(0.0, 0.0);
        Complex result = c.divide(divisor);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_DivisorInfinite_FiniteDividend_Result() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result = c.divide(divisor);
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_DivisorInfinite_InfiniteDividend_Result() {
        // If dividend is also infinite, it should follow NaN logic or specific branch
        // Based on code: if (isNaN || divisor.isNaN) returns NaN. 
        // If divisor is infinite and dividend is not NaN, it returns ZERO.
        // If dividend is infinite, it hits the NaN check if we use Double.NaN, 
        // but if dividend is just very large, it proceeds.
        Complex c = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex divisor = new Complex(Double.POSITIVE_INFINITY, 0.0);
        // The code doesn't explicitly check if 'isInfinite()' is true for dividend 
        // before the divisor check, it only checks divisor.isInfinite() && !isInfinite()
        // If both are infinite, it goes to the calculation part.
        Complex result = c.divide(divisor);
        // Depending on implementation of division of infinities, but we test the branch.
        Assert.assertNotNull(result);
    }

    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // divisor.getReal() = 1.0, divisor.getImaginary() = 2.0
        // |1.0| < |2.0| is true
        Complex c = new Complex(4.0, 6.0);
        Complex divisor = new Complex(1.0, 2.0);
        // (4+6i)/(1+2i) = [(4+6i)(1-2i)] / [1^2 + 2^2] 
        // = [4 - 8i + 6i - 12i^2] / 5 = [4 + 12 - 2i] / 5 = 16/5 - 2/5i = 3.2 - 0.4i
        Complex result = c.divide(divisor);
        Assert.assertEquals(3.2, result.getReal(), EPSILON);
        Assert.assertEquals(-0.4, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_AbsC_GreaterThanOrEqual_AbsD() {
        // divisor.getReal() = 2.0, divisor.getImaginary() = 1.0
        // |2.0| < |1.0| is false
        Complex c = new Complex(4.0, 6.0);
        Complex divisor = new Complex(2.0, 1.0);
        // (4+6i)/(2+1i) = [(4+6i)(2-1i)] / [2^2 + 1^2]
        // = [8 - 4i + 12i - 6i^2] / 5 = [8 + 6 + 8i] / 5 = 14/5 + 8/5i = 2.8 + 1.6i
        Complex result = c.divide(divisor);
        Assert.assertEquals(2.8, result.getReal(), EPSILON);
        Assert.assertEquals(1.6, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Equality() {
        Complex c1 = new Complex(1.0, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 0.0);
        Complex result = c1.divide(divisor);
        Assert.assertEquals(c2, result);
    }
}
